#include <iostream>
#include <queue>
#include <tuple>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int k;
    cin >> k;
    vector<vector<long long>> feeds(k);
    for (auto& f : feeds) {
        int m;
        cin >> m;
        f.resize(m);
        for (auto& x : f) cin >> x;
    }
    using T = tuple<long long, int, int>;
    priority_queue<T, vector<T>, greater<T>> heap;
    for (int i = 0; i < k; i++)
        if (!feeds[i].empty()) heap.emplace(feeds[i][0], i, 0);
    bool first = true;
    while (!heap.empty()) {
        auto [v, i, j] = heap.top();
        heap.pop();
        if (!first) cout << ' ';
        cout << v;
        first = false;
        if (j + 1 < (int)feeds[i].size()) heap.emplace(feeds[i][j + 1], i, j + 1);
    }
    cout << '\n';
    return 0;
}
